/* From Uiverse.io by JaydipPrajapati1910 - Tags: input, search, border, search bar */
.__UIV_SCOPE__ .group {
  display: flex;
  line-height: 28px;
  align-items: center;
  position: relative;
  max-width: 190px;
}

.__UIV_SCOPE__ .input {
  height: 40px;
  line-height: 28px;
  padding: 0 1rem;
  width: 100%;
  padding-left: 2.5rem;
  outline: none;
  background: linear-gradient(180deg,     rgb(56, 56, 56) 0%, rgb(36, 36, 36)   66%, rgb(41, 41, 41) 100%);
  color: #fff;
  transition: .3s ease;
  border: 2px solid;
  border-image: conic-gradient( #00F260, #0575E6,#64f38c) 1;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #fff;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  color: #999;
}

.__UIV_SCOPE__ .icon {
  position: absolute;
  left: 1rem;
  fill: #fff;
  width: 1rem;
  height: 1rem;
}
